import itertools
import json

def solve():
    houses = [1, 2, 3, 4]

    # Attributes and values
    Names = ["Eric", "Peter", "Arnold", "Alice"]
    Smoothies = ["dragonfruit", "cherry", "desert", "watermelon"]
    Cigars = ["blue master", "pall mall", "dunhill", "prince"]
    Heights = ["tall", "average", "short", "very short"]
    Phones = ["google pixel 6", "samsung galaxy s21", "iphone 13", "oneplus 9"]

    def pos_of(value, arr):
        return arr.index(value)

    solutions = []

    # Iterate over phones with constraint 3 (directly left) applied early
    for phones_perm in itertools.permutations(Phones):
        # 3. Samsung Galaxy S21 is directly left of iPhone 13.
        if not (pos_of("samsung galaxy s21", phones_perm) + 1 == pos_of("iphone 13", phones_perm)):
            continue

        # Iterate over heights with constraint 7 and 8 applied
        for heights_perm in itertools.permutations(Heights):
            # 7. The person who is tall is in the third house.
            if heights_perm[2] != "tall":
                continue
            # 8. Very short <-> iPhone 13.
            if heights_perm[pos_of("iphone 13", phones_perm)] != "very short":
                continue

            # Iterate over cigars with constraints 9, 10, 4, and 6 applied
            for cigars_perm in itertools.permutations(Cigars):
                # 9. Blue Master is not in the first house.
                if cigars_perm[0] == "blue master":
                    continue
                # 10. Dunhill smoker is short.
                if heights_perm[pos_of("dunhill", cigars_perm)] != "short":
                    continue
                # 4. Dunhill smoker is to the right of the very short person.
                if pos_of("dunhill", cigars_perm) <= pos_of("very short", heights_perm):
                    continue
                # 6. Prince smoker <-> OnePlus 9.
                if pos_of("prince", cigars_perm) != pos_of("oneplus 9", phones_perm):
                    continue

                # Iterate over smoothies with constraints 2, 5, 13 applied
                for smoothies_perm in itertools.permutations(Smoothies):
                    # 2. Dunhill smoker likes Cherry smoothies.
                    if pos_of("dunhill", cigars_perm) != pos_of("cherry", smoothies_perm):
                        continue
                    # 5. Watermelon is to the right of Desert.
                    if pos_of("watermelon", smoothies_perm) <= pos_of("desert", smoothies_perm):
                        continue
                    # 13. Dragonfruit <-> Pall Mall
                    if pos_of("dragonfruit", smoothies_perm) != pos_of("pall mall", cigars_perm):
                        continue

                    # Iterate over names with constraints 1, 11, 12 applied
                    for names_perm in itertools.permutations(Names):
                        # 11. Peter is not in the third house.
                        if names_perm[2] == "Peter":
                            continue
                        # 1. Dragonfruit smoothie lover is Eric.
                        if names_perm[pos_of("dragonfruit", smoothies_perm)] != "Eric":
                            continue
                        # 12. Arnold <-> Google Pixel 6
                        if names_perm[pos_of("google pixel 6", phones_perm)] != "Arnold":
                            continue

                        # All constraints satisfied
                        solutions.append({
                            "names": names_perm,
                            "smoothies": smoothies_perm,
                            "cigars": cigars_perm,
                            "heights": heights_perm,
                            "phones": phones_perm
                        })

    # Prepare output from the (presumably unique) solution
    if not solutions:
        raise RuntimeError("No solution found")

    sol = solutions[0]
    header = ["House", "Name", "favorite smoothie", "favorite cigar", "height", "phone model"]
    rows = []
    for i in range(4):
        rows.append([
            str(i + 1),
            sol["names"][i],
            sol["smoothies"][i],
            sol["cigars"][i],
            sol["heights"][i],
            sol["phones"][i]
        ])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

    print(json.dumps(output, ensure_ascii=False))

if __name__ == "__main__":
    solve()
